import{d as g,C as a,o as p,c as h,E as i,a3 as t}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"蹇卦","description":"第三十九卦·水山蹇——险在前而能止。蹇是处境，不是动作；见险而能止，是看清这份处境之后提炼出的应对智慧。","frontmatter":{"title":"蹇卦","description":"第三十九卦·水山蹇——险在前而能止。蹇是处境，不是动作；见险而能止，是看清这份处境之后提炼出的应对智慧。","category":"hexagram","aliases":["蹇","水山蹇"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/39-shuishanjian.md","filePath":"yijing/hexagrams/39-shuishanjian.md","lastUpdated":1789987057000}'),d={name:"yijing/hexagrams/39-shuishanjian.md"},b=g({...d,setup(u){const o=[{id:"wang",term:"往",pinyin:"wǎng",meaning:"向外、前进。",context:"泰卦「小往大来」、否卦「大往小来」皆以「往」为外出。四个「往蹇」的用例里，往 + 险难名词语法通顺，往 + 止则自相矛盾——这是「蹇」不含「止」义的内部铁证。"},{id:"lai",term:"来",pinyin:"lái",meaning:"向内、退返，与「往」对举。",context:"初六「来誉」、九三「来反」、六四「来连」、上六「来硕」，皆以「来」为退返本位。"},{id:"fan",term:"反",pinyin:"fǎn",meaning:"折返，是空间动作，不是「反躬自省」。",context:"复卦「反复其道」、泰卦九三「无往不复」。"},{id:"lian",term:"连",pinyin:"lián",meaning:"联结、依靠。",context:"六四被九三、九五两阳爻环抱。此处取「联结」义，依据小象「当位实也」的肯定语气；「牵连拖累」的读法仍留有模糊地带。"},{id:"peng",term:"朋",pinyin:"péng",meaning:"同类聚合，不是「友谊」。",context:"呼应坤卦「西南得朋」「乃与类行」。"},{id:"shuo",term:"硕",pinyin:"shuò",meaning:"历经消耗仍完整保留的成果。",context:"剥卦上九「硕果不食」。"},{id:"jianjian",term:"蹇蹇",pinyin:"jiǎn jiǎn",meaning:"险难反复叠加。叠字表程度加深，不是「止而反身」。"},{id:"feigong",term:"匪躬",pinyin:"fěi gōng",meaning:"不是因自身私利所致。匪即非，躬即自身。",context:"六二小象「终无尤也」，以「匪躬之故」为支撑判定的理由。"},{id:"daren",term:"大人",pinyin:"dà rén",meaning:"德位兼备、能带人出险的人。",context:"卦辞「利见大人」的承诺，在上六兑现——所见正是九五。"}],e=[{position:"初六",type:"yin",text:"往蹇来誉。",xiang:"往蹇来誉，宜待也。",textModern:"前往则遇险，退返则得称许。尚未深入险境、退路仍在时，止步本身就是值得称许的事。",xiangModern:"往蹇来誉，是说此时宜于等待。"},{position:"六二",type:"yin",text:"王臣蹇蹇，匪躬之故。",xiang:"王臣蹇蹇，终无尤也。",textModern:"身为王臣，险难反复叠加；这份艰难不是因自身私利招致。守得住这份清白，终究无过咎。",xiangModern:"王臣蹇蹇而终无过咎——因为这份苦不为己。"},{position:"九三",type:"yang",text:"往蹇来反。",xiang:"往蹇来反，内喜之也。",textModern:"前往则入险，折返则回本位。艮之主处在山域最后的边界，这一次折返是结构性的回归，内心安然。",xiangModern:"往蹇来反，因为回到本位而内心喜悦。"},{position:"六四",type:"yin",text:"往蹇来连。",xiang:"往蹇来连，当位实也。",textModern:"前往则遇险，退返则联结。刚入坎险、自知柔弱，转而依靠左右两阳爻——老实待在能左右逢源的位置上，本身就是踏实。",xiangModern:"往蹇来连，因为当位而踏实。"},{position:"九五",type:"yang",text:"大蹇朋来。",xiang:"大蹇朋来，以中节也。",textModern:"险难的核心与君位的责任重合，是为大蹇；而同类自然聚拢而来。不靠乞求，靠中正有节的定力。",xiangModern:"大蹇朋来，因为中正有节。"},{position:"上六",type:"yin",text:"往蹇来硕，吉，利见大人。",xiang:"往蹇来硕，志在内也。利见大人，以从贵也。",textModern:"历尽全险而带回完整的成果，吉；宜见大人。脱险而不弃同伴，心仍系着尚在险中的九五。",xiangModern:"往蹇来硕，志在于内——心系险中的同伴；利见大人，是追随尊贵者。"}];return(m,n)=>{const r=a("DaoHexagramViewer"),s=a("DaoHexagramYaoCards"),l=a("DaoKeywordCards");return p(),h("div",null,[i(r,{name:"蹇",fullName:"水山蹇",upper:"☵",lower:"☶",guaCi:"蹇，利西南，不利东北。利见大人，贞吉。",pinyin:["jiǎn"],element:"金",direction:"西",insight:"山上有水，行路维艰。止不是认输，是看清险在前而不硬闯——先反身修德，再等同类相聚。",guaSlug:"39shuishanjian",lines:e}),n[0]||(n[0]=t("",11)),i(s,{element:"金",guaSlug:"39shuishanjian",glossary:o,items:e}),n[1]||(n[1]=t("",27)),i(l,{title:"字词释义",items:[{term:"蹇",pinyin:["jiǎn"],meaning:"艰难、跛足、难行。是「处境」，不是「动作」——这一点靠爻辞用法钉死：四个「往蹇」中，往 + 险难名词语法通顺，往 + 止则自相矛盾，故「蹇」字本身不含「止」义。"},{term:"往",pinyin:["wǎng"],meaning:"向外、前进。泰卦「小往大来」、否卦「大往小来」皆以「往」为外出。"},{term:"来",pinyin:["lái"],meaning:"向内、退返，与「往」对举。"},{term:"反",pinyin:["fǎn"],meaning:"折返，是空间动作，不是「反躬自省」。复卦「反复其道」、泰卦九三「无往不复」。"},{term:"连",pinyin:["lián"],meaning:"联结、依靠。六四被九三、九五两阳爻环抱；取此读法的依据是小象「当位实也」的肯定语气。"},{term:"朋",pinyin:["péng"],meaning:"同类聚合，不是「友谊」。坤卦「西南得朋」「乃与类行」。"},{term:"硕",pinyin:["shuò"],meaning:"历经消耗仍完整保留的成果。剥卦上九「硕果不食」。"},{term:"誉",pinyin:["yù"],meaning:"称许、声誉。初六「来誉」，是退返本位所得的称许。"},{term:"蹇蹇",pinyin:["jiǎn","jiǎn"],meaning:"险难反复叠加。叠字表程度加深。"},{term:"匪躬",pinyin:["fěi","gōng"],meaning:"不是因自身私利所致。匪即非，躬即自身。"},{term:"大蹇",pinyin:["dà","jiǎn"],meaning:"险难的核心与责任的核心重合之处，故曰「大」。"},{term:"大人",pinyin:["dà","rén"],meaning:"德位兼备、能带人出险的人。卦辞「利见大人」，于上六兑现为九五。"},{term:"反身修德",pinyin:["fǎn","shēn","xiū","dé"],meaning:"象传语。回头修自己，而不是向外强求——蹇卦给出的第一个动作。"}]}),n[2]||(n[2]=t("",26))])}}});export{x as __pageData,b as default};
